mapper.select:
SELECT panel_id AS panelId, panel_code AS panelCode, name, category, gene_count AS geneCount, use_yn AS useYn, created_at AS createdAt FROM gene_panels WHERE 1=1 AND tenant_id = #{tenantId}
AND (name ILIKE '%' || #{search} || '%' OR panel_code ILIKE '%' || #{search} || '%')
ORDER BY panel_id DESC LIMIT #{limit} OFFSET #{offset}
